import { copyFileSync, mkdirSync, writeFileSync } from "node:fs";

mkdirSync("dist", { recursive: true });
copyFileSync("temperature.mjs", "dist/temperature.mjs");
writeFileSync("dist/build.json", `${JSON.stringify({ entry: "temperature.mjs" }, null, 2)}\n`);
console.log("built dist/temperature.mjs");
